pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockDelta) public {
        vm.assume(blockDelta > 0 && blockDelta <= 256);
        address alice = address(0x1000);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(0x1)));
        uint256 recordBlock = block.number + 1;
        vm.roll(recordBlock + blockDelta - 1);
        bool ok = false;
        vm.prank(alice);
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}

