// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 rollTo) public {
        // admissible: rollTo is the block height after lockInGuess
        // We need at least one block after the transaction that calls lockInGuess
        vm.assume(rollTo > block.number);

        // Setup: fund the contract and the caller
        vm.deal(address(this), 2 ether);
        vm.deal(address(c), 10 ether);

        // lockInGuess with 1 ether
        c.lockInGuess{value: 1 ether}(guessHash);

        // Warp to the stored block height (which would be block.number + 1 for correct contract,
        // block.number + 2 for mutant). We need to compute the stored block, but it's private.
        // Instead, we just roll to the height where the stored block equals current block for the mutant,
        // which is block.number+1 (stored) + 1 more = original + 2.
        // However, since we don't know the stored block directly, we use an indirect approach:
        // We roll to an arbitrary future block and try to settle.
        // The property is: for correct contract, settle MUST revert if block.number == stored.block,
        // but for mutant, it succeeds when block.number == stored.block (since the stored block is delayed).

        // But we can compute the expected stored block based on current block after lockInGuess.
        // Since lockInGuess stores block.number + 1 (or +2 for mutant), we can roll to that exact block.
        uint256 expectedStoredBlock = block.number + 1; // Correct contract stores +1
        vm.roll(expectedStoredBlock);

        // Try to settle
        try c.settle() {
            // For correct contract, this should fail because block.number == stored.block, 
            // but requirement is block.number > stored.block.
            // For mutant, stored.block = original block.number + 2, so here block.number = original+1 < stored,
            // settle also fails because block.number < stored (require block.number > stored.block).
        } catch {
            // Correct: settle reverts.
        }

        // Actually the property: After lockInGuess, settle must revert at the block where correct contract thinks it's too early,
        // but the mutant makes it succeedable one block earlier?
        // Let's re-evaluate: The correct contract stores block.number+1, and requires block.number > stored.block.
        // So settle is callable at block.number >= stored.block + 1.
        // Mutant stores block.number+2, so settle is callable at block.number >= stored.block + 1 = original+3.
        // That means mutant delays settle by one block (original+3 vs original+2).
        // The difference: at block original+2, correct contract can settle (since stored+1 = original+1+1 = original+2),
        // but mutant cannot (stored = original+2, need > original+2).
        // So we can check that at block original+2, correct succeeds and mutant fails.

        vm.roll(expectedStoredBlock + 1); // original+2
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok); // Correct should succeed; mutant will revert because block.number still <= stored.block (original+2 vs original+2)
    }
}

