contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint8 extraBlocks) public {
        // Bound extraBlocks to at least 1 so settle block is strictly after lockInGuess block
        vm.assume(extraBlocks > 0);

        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance by the extra blocks so settle is clearly in a later block
        vm.roll(block.number + extraBlocks);

        // Now try to settle; record whether it reverted
        bool succeeded;
        vm.prank(actor);
        try c.settle() { succeeded = true; } catch { succeeded = false; }

        // After successful settle, the contract must have paid out 2 ether, reducing its balance
        // But the ref version stores block.number+1 -> settlement always requires at least one block gap
        // Bug stores block.number -> settlement may succeed immediately when extraBlocks=0, but here extraBlocks>0 so both versions may succeed.
        // The key invariant: the stored block must be > block.number at the time of lockInGuess.
        // We can check this by reading guesses[actor].block right after lockInGuess:
        // We'll re-query it: it's a public mapping, so getter exists.
    }
}

