pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, bytes32 hash1, bytes32 hash2) public {
        // 1. Restrict to a plausible address that is not zero
        vm.assume(actor != address(0));
        // 2. Provide the required 1 ether for each lockInGuess call
        vm.deal(actor, 2 ether);
        vm.startPrank(actor);
        // First guess
        c.lockInGuess{value: 1 ether}(hash1);
        // Attempt second guess on the same actor (buggy version allows it, reference does not)
        try c.lockInGuess{value: 1 ether}(hash2) {
            // If the second call succeeds, we can observe the stored block
            uint storedBlock = c.guesses(actor).block;
            // 3. Assert that the stored block equals the current block.number + 1
            // The reference always reverts on the second call, so this branch is unreachable for it, making the assertion vacuously true.
            // The buggy version allows the second call, and the stored block may be block.number + 1 (but this is not guaranteed to differ from the first unless blocks advance).
            // However, the fuzzer can find scenarios where the assertion fails because the stored block is from the second call and equal to block.number + 1,
            // but the critical difference is that the reference should never have allowed the second call. We wrap the invariant around the success path.
            // The general rule: if lockInGuess succeeds, then guesses[actor].block == block.number + 1.
            assertEq(storedBlock, block.number + 1);
        } catch {
            // If the second call fails, the reference behavior is correct.
            // We can check that the stored block is unchanged (still block1+1).
            // But since the second call reverted, no state change occurred, which is acceptable for the reference.
            // Assert that the reference still satisfies the invariant after a revert.
            assertEq(c.guesses(actor).block, block.number + 1);
        }
        vm.stopPrank();
    }
}

