contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzz_block, bytes32 fuzz_guess1, bytes32 fuzz_guess2) public {
        address actor = address(0x1);
        vm.deal(actor, 5 ether);
        // Warp to a future block to avoid immediate settle constraints
        vm.roll(fuzz_block + 10);
        // First lockInGuess call
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(fuzz_guess1);
        uint256 block1 = c.guesses(actor).block;
        // Second lockInGuess call
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", fuzz_guess2));
        // If second call succeeds, the stored block must not be updated (must equal the first block)
        // If it reverts, the property holds trivially
        if (ok) {
            uint256 block2 = c.guesses(actor).block;
            assertTrue(block2 == block1);
        } else {
            assertTrue(true);
        }
    }
}

