pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash) public {
        // 1. Ensure the guess is wrong with high probability: fuzzed guessHash is likely not the answer.
        //    We do not constrain guessHash to keep the domain wide.
        // 2. Prepare the scenario:
        address player = makeAddr("player");
        vm.deal(player, 2 ether);
        // Fund C with 2 ether to allow settle payout
        vm.deal(address(c), 2 ether);
        // Player makes a lockInGuess with a wrong guess
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guessHash);
        // Advance block number beyond lock block
        vm.roll(block.number + 2);
        // 3. Capture settle outcome and final balance
        uint256 balanceBefore = address(player).balance;
        bool settledOk;
        try c.settle() { settledOk = true; } catch { settledOk = false; }
        uint256 balanceAfter = address(player).balance;
        // 4. Assert: player balance should NOT increase when guess is wrong.
        //    This holds for reference C (no transfer on wrong guess), but fails for the mutant (always transfers).
        assertTrue(balanceAfter == balanceBefore);
    }
}

