pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Fund the contract with 2 ether so a transfer can succeed
        vm.deal(address(c), 2 ether);

        // Actor locks in a guess that is certainly wrong: keccak256 of a known value
        bytes32 fakeHash = keccak256("wrong");
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(fakeHash);

        // Advance past the guess block so the block check passes
        vm.roll(block.number + 2);

        // Record actor's ETH balance before settle
        uint256 balBefore = actor.balance;

        vm.prank(actor);
        try c.settle() {
            // In the buggy version, settle always transfers 2 ether
            // In the correct version, nothing is transferred because the guess is wrong
        } catch {
            // If settle reverts, balance doesn't change
        }

        uint256 balAfter = actor.balance;

        // Property: actor's ETH balance never increases when the guess is wrong
        assertTrue(balAfter == balBefore, "ETH balance should not increase on wrong guess");
    }
}

