pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, bytes32 blockHash, uint8 blockOffset) public {
        // 1. domain: keep blockOffset in [2, 10] to ensure block.number > guesses[msg.sender].block
        blockOffset = uint8(bound(blockOffset, 2, 10));
        address alice = makeAddr("alice");
        vm.deal(alice, 1 ether);

        // fund the contract with 2 ether so transfer is possible
        vm.deal(address(c), 3 ether);

        // alice locks in a guess
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(guessHash);

        // advance block number so settle() can be called
        vm.roll(block.number + blockOffset);
        // set blockhash to a value that differs from guessHash to guarantee wrong guess
        bytes32 wrongAnswer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        vm.assume(wrongAnswer != guessHash);

        uint256 balBefore = address(c).balance;
        vm.prank(alice);
        c.settle();
        uint256 balAfter = address(c).balance;

        // reference: no transfer on wrong guess => balance unchanged; mutant transfers 2 ether => balance decreases
        assertTrue(balAfter == balBefore);
    }
}

