pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 blockAdvance) public {
        // Restrict to admissible domain: advance at least 1 block beyond the guess block.
        blockAdvance = bound(blockAdvance, 1, 256);

        // Fund the contract with exactly 2 ether so a transfer leaves it with 0.
        vm.deal(address(c), 2 ether);

        // Set up a caller with a wrong guess.
        address caller = address(0xBEEF);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guess);

        // Advance blocks so settle is allowed.
        vm.roll(block.number + blockAdvance);

        // Record contract balance before settle.
        uint256 balBefore = address(c).balance;

        vm.prank(caller);
        try c.settle() { } catch { }

        // The rule: contract's ETH balance is unchanged when the guess is wrong.
        // (The guess is wrong because blockhash of a future block is not guessable.)
        assertEq(address(c).balance, balBefore);
    }
}

