import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        payable(address(c)).transfer(0);
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 wrongGuess, uint256 callValue) public {
        vm.assume(callValue == 1 ether);
        address player = makeAddr("player");
        vm.deal(player, 2 ether);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number - 1)));
        if (wrongGuess == answer) return;

        vm.prank(player);
        c.lockInGuess{value: 1 ether}(wrongGuess);

        vm.roll(block.number + 5);

        uint256 balanceBefore = address(c).balance;
        vm.prank(player);
        try c.settle() {} catch {}

        assertTrue(address(c).balance == balanceBefore || address(c).balance == balanceBefore - 2 ether);
    }
}

