pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint256 blockDelay) public {
        address player = address(0x1000);
        uint256 deposit = 1 ether;

        // Lock-in needs exactly 1 ether. Provide funds and lock in the guess.
        vm.deal(player, deposit);
        vm.prank(player);
        c.lockInGuess{value: deposit}(guess);

        // Move past the lock-in block (block after lockIn). Block delay must be at least 2.
        bound(blockDelay, 2, type(uint256).max);
        vm.roll(block.number + blockDelay);

        // Ensure contract has enough balance for payout. It should have exactly 1 ether from lockIn + 1 ether from constructor.
        // To see a potential difference we must ensure balance >= 2 ether so a buggy payout can succeed.
        // The constructor requires 1 ether, and lockIn adds 1 ether, so balance == 2 ether.
        // Pre-condition: assert balance == 2 ether.
        assertEq(address(c).balance, 2 ether, "pre-condition: balance should be 2 ether");

        // Call settle. The guess we locked in is arbitrary.
        // For the correct contract, if guess != answer, no payout, balance stays 2 ether.
        // For the buggy contract, if guess != answer, 2 ether is sent to player, balance becomes 0.
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        // admissible: settle should not revert (block delay > 0 ensures block.number > guesses.block).
        assertTrue(ok, "settle should not revert");

        // The property: After settle with a non-matching guess (the fuzzer will find a guess that does NOT match the blockhash),
        // the contract's balance must NOT decrease below 2 ether under the correct contract.
        // Under the buggy contract, when guess != answer, it transfers 2 ether and balance becomes 0, violating the rule.
        assertTrue(address(c).balance >= 2 ether, "balance must remain at least 2 ether after settle with non-matching guess");
    }
}

