contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, address caller) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(guessHash != bytes32(0));

        // fund caller with 1 ether and lock in guess
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessHash);

        // advance past the lock-in block
        vm.roll(block.number + 2);
        vm.warp(block.timestamp + 2);

        // ensure contract balance is >= 2 ether (1 from constructor? N/A, constructor already funded with 1 ether during setUp?)
        // Actually, we need to fund the contract with an additional 1 ether so that it can potentially pay out.
        // Constructor requires 1 ether, so we transfer 1 ether to contract externally.
        vm.deal(address(c), address(c).balance + 1 ether);

        uint256 balanceBefore = address(c).balance;
        bool settled;
        try c.settle() returns () {
            settled = true;
        } catch {
            settled = false;
        }
        uint256 balanceAfter = address(c).balance;

        // If settle succeeded, check invariant: payout only occurs when guess matches answer.
        // We cannot predict the answer, so we enforce a general property:
        // If balance decreased, it must have decreased by exactly 2 ether and must now be >= 0.
        // But the correct contract only pays when guess matches; the buggy one pays when it doesn't.
        // The property: balanceAfter >= balanceBefore - 2 ether, and if balanceAfter < balanceBefore, then balanceBefore - balanceAfter == 2 ether.
        // However, the key differentiator: the buggy version pays on mismatch. Since the fuzzer supplies guessHash,
        // we can express: if settle succeeded, the contract balance should only decrease if guessHash == answer (unknown).
        // Instead, we check a broader invariant true for the correct contract for ALL inputs:
        // The contract's balance never drops below the sum of all locked guesses (which is 1 ether in this test).
        // After settle, the locked guess is consumed, but if no payout, balance should still contain that 1 ether.
        // The correct contract holds: if settled, then balanceAfter >= 1 ether.
        // The buggy contract may pay out on mismatch, dropping balance below 1 ether.
        assertTrue(!settled || balanceAfter >= 1 ether);
    }
}

