pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 guessHash, uint8 blockOffset) public {
        // Restrict blockOffset to a reasonable range to keep the fuzz domain wide but admissible
        vm.assume(blockOffset > 0 && blockOffset <= 10);

        address guesser = makeAddr("guesser");
        vm.deal(guesser, 2 ether);

        // guesser locks in a guess
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Advance blocks so that settle can be called
        vm.roll(block.number + blockOffset);

        // Warp to a point where the blockhash for guesses[guesser].block is available (it is available for the last 256 blocks)
        // The block used in lockInGuess is block.number + 1 of the lock transaction.
        // After advancing by blockOffset, we are past that block, so blockhash should be available.

        uint256 balanceBefore = guesser.balance;
        try c.settle() {
            // If no revert, check that guesser received exactly 2 ether when the guess was correct.
            // We cannot observe the guess correctness directly, but we can check the invariant:
            // If settle() succeeded and the guess matched the answer, balance increase must be 2 ether.
            // The bug violates this by transferring only 1 ether.
            uint256 balanceAfter = guesser.balance;
            uint256 received = balanceAfter - balanceBefore;

            // The invariant: if the guess was correct (settle succeeded without revert due to balance check),
            // the received amount must be either 0 (incorrect guess) or exactly 2 ether (correct guess).
            // The bug makes it 1 ether for correct guesses, breaking the "if paid, pay exactly 2 ether" rule.
            // However, the transfer only happens when guess == answer, so for a correct guess, received == 2 ether.
            // We can assert: received == 0 || received == 2 ether
            // But the bug version produces received == 1 ether for correct guesses.
            // To guarantee the assertion detects the bug, we need settle to succeed AND guess to be correct.
            // Since the fuzzer provides guessHash, it may or may not match the blockhash.
            // The property "if settle does not revert, then received is either 0 or 2 ether" holds for the reference
            // and fails for the bug when a correct guess (received == 1 ether) occurs.
            // We must also ensure the require(address(this).balance >= ...) passes in both versions.
            // The contract initially has 2 ether (1 from constructor + 1 from lockInGuess).
            // Reference requires >= 2 ether, bug requires >= 1 ether. Both hold.
            // Therefore, settle completes and transfers.
            // The assertion:
            assertTrue(received == 0 || received == 2 ether);
        } catch {
            // If revert, the invariant is vacuously true (no transfer occurred).
            // We can assert true to pass.
            assertTrue(true);
        }
    }
}

