        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Warp to the block after the lock block (current block.number + 1 + offset)
        uint256 settleBlock = block.number + blockOffset;
        vm.roll(settleBlock);

        // Warp to block after settle block so blockhash is available
        vm.roll(settleBlock + 1);

        uint256 balanceBefore = address(c).balance;

