pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 guess, uint8 futureBlocks) public {
        // futureBlocks must be >= 1 so settle sees a past block
        vm.assume(futureBlocks >= 1);

        // Deploy a neutral helper that simply receives ether; it acts as the guesser.
        // We need a contract because a raw fuzzed address is an EOA with no code;
        // here we use the helper ONLY to reliably receive ether. It does NOT revert.
        Helper guesser = new Helper();
        vm.deal(address(guesser), 3 ether);

        // Record initial balances
        uint256 cBefore = address(c).balance;
        uint256 gBefore = address(guesser).balance;

        // locker: lockInGuess with 1 ether
        vm.prank(address(guesser));
        c.lockInGuess{value: 1 ether}(guess);

        // Warp to a block number strictly after the guess block
        uint256 lockBlock = block.number;
        vm.roll(lockBlock + futureBlocks);

        // settle
        vm.prank(address(guesser));
        c.settle();

        // After settle, the sum of contract balance change and guesser balance change
        // should equal zero (modulo Ether sent by other users during setup).
        // The only Ether flows are: initial 1 ether to c, 1 ether from guesser to c,
        // and possible 2 ether from c to guesser (win).
        // So: total system (c + guesser) change from start = 0.
        uint256 cAfter = address(c).balance;
        uint256 gAfter = address(guesser).balance;
        int256 cDelta = int256(cAfter) - int256(cBefore);
        int256 gDelta = int256(gAfter) - int256(gBefore);
        assertTrue(cDelta + gDelta == 0);
    }
}

contract Helper {
    // This contract simply accepts ETH; used as a guesser whose balance can be tracked.
    receive() external payable {}
}

