        // The property: calling settle again must revert (because block is 0) in the reference,
        // but the buggy version allows it and would attempt to pay out if guess matched.
        // To observe the difference, we re-lock a winning guess, settle it, and then try to settle again.
        // However the property must hold for all inputs; we use the fact that after the first settle
        // the sender's block is either 0 (reference) or the old block (bug). A second call to settle
        // must revert in the reference (since require(block != 0) fails).

        vm.prank(sender);
        try c.settle() returns (bool) {
            // If it succeeds, the bug is present (block wasn't cleared)
            // But we need a general assertion: reference always reverts here, bug sometimes succeeds.
            // To make the assertion work, we combine with an invariant that after a non-winning settle,
            // the sender's state is reset to 0 in reference, so a second settle reverts.
            // We assert that the second settle reverts.
            assertTrue(false); // buggy path: second settle succeeded when it shouldn't
        } catch {
            assertTrue(true); // reference path: second settle correctly reverted
        }
    }
}

