pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(uint256 blockDistance, uint256 guessSeed) public {
        // blockDistance bounds: 1 to keep guess block in past (original requires past),
        // but also allow 0 so fuzzer can trigger the >= bug (same block).
        blockDistance = bound(blockDistance, 0, 256);
        // Setup: fund a guesser and lock in a guess made from blockhash of target block.
        address guesser = address(0x1234);
        vm.deal(guesser, 2 ether);
        // Advance chain to a base block so we can reference future blocks.
        vm.roll(100);
        uint256 targetBlock = block.number + blockDistance;
        // If targetBlock is the current block, its hash is not yet available; blockhash will return 0.
        // Compute guess based on blockhash of targetBlock (0 if same block).
        bytes32 answer = keccak256(abi.encodePacked(blockhash(targetBlock)));
        // Derive a guess from guessSeed that may or may not match answer.
        bytes32 guess = guessSeed == 0 ? answer : bytes32(guessSeed);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guess);
        // Advance chain to targetBlock so that settle can be called at exactly that block.
        vm.roll(targetBlock);
        // Now settle. If targetBlock == current block, buggy version allows it (>=), correct requires >.
        bool settled;
        uint256 balBefore = address(c).balance;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }
        uint256 balAfter = address(c).balance;
        // If settle did not revert, the contract must have paid out 2 ether only if the guess was correct
        // AND the block used was strictly in the past (block.number > guesses block).
        // The reference contract reverts when block.number == guesses block (same block),
        // therefore it never pays out in that case. The buggy version does not revert for same block,
        // and may pay out if guess matches blockhash(block.number) (which is always 0).
        // General rule: after a non-reverting settle, if ether was transferred (balance decreased by 2 ether),
        // then the block used MUST be strictly less than the current block number.
        // We can check: if balance decreased by 2, then guesses[guesser].block was < block.number.
        // Because guesses.block is set to 0 after settle, we cannot read it after.
        // We instead catch the behavior: if settled is true, then the balance change reflects payout correctness.
        // A transfer of 2 ether implies guess matched answer. In correct contract, same-block settle reverts,
        // so settled==true implies blockDistance>0. In buggy, settled can be true for blockDistance==0,
        // and if guess matched (which is easy: guess==0x0...0 matches blockhash(targetBlock)==0),
        // it pays out, violating the invariant that payout only occurs for past blocks.
        bool paidOut = balBefore > balAfter && balBefore - balAfter == 2 ether;
        if (settled) {
            // If it settled and paid out, the block used must have been strictly in the past.
            // The only way to have blockDistance == 0 is if the block was the same, which is illegal.
            // The correct contract never pays out for blockDistance == 0; the buggy one does.
            assertTrue(!paidOut || blockDistance > 0);
        } else {
            // If it reverted, no payout occurred (invariant holds vacuously).
            assertTrue(true);
        }
    }
}

