pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        vm.deal(address(c), 1 ether);
    }
    function testFuzz_property(uint256 blockDelta, bytes32 guessHash) public {
        // blockDelta: 0 means same-block settlement (bug trigger), >0 means future block
        // guessHash: the keccak256 hash that will be matched against blockhash
        vm.assume(blockDelta < 256); // keep within blockhash window
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);
        // advance to the settlement block
        if (blockDelta > 0) {
            vm.roll(block.number + blockDelta);
        } else {
            // stay at the same block for the bug-trigger case
        }
        // record balance before settle
        uint256 balanceBefore = address(c).balance;
        bool settled;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }
        uint256 balanceAfter = address(c).balance;
        // General rule: if settle succeeds, the balance change must be exactly -2 ether only when the guess matches a PAST blockhash
        // For the buggy version, when blockDelta==0, settle can succeed and transfer 2 ether even though block.number == guess.block,
        // which the reference contract forbids. The reference contract will revert in that case.
        if (settled) {
            // For the reference contract, this can only happen when blockDelta > 0 (past block)
            // In that case, balance change is either -2 ether (if guess matches) or 0 (if not)
            assertTrue(balanceBefore - balanceAfter == 2 ether || balanceBefore == balanceAfter);
        } else {
            // If it reverted, balance must be unchanged
            assertTrue(balanceBefore == balanceAfter);
        }
    }
}

