pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint64 blockDelta) public {
        // blockDelta = 0 forces lock block = block.number + 1; settler must be able to call settle in same block for bug
        // Bound blockDelta to keep in admissible domain (future block + small delta)
        bound(blockDelta, 0, 100);
        vm.roll(block.number + 1 + blockDelta);

        address settler = makeAddr("settler");
        vm.deal(settler, 1 ether);
