        // Warp to the exact block where the guess's block field is set (lock block = previous block.number + 1)
        // lockInGuess set block = block.number + 1, so after lockInGuess the guessed block is the next block.
        // After lockInGuess, we are at block N; guessed block = N; we warp to that block.
        vm.roll(block.number + 1);

        // Try to settle
        vm.prank(settler);
        bool success;
        try c.settle() {
            success = true;
        } catch {
            success = false;
        }

        // Rule: if settle succeeded, the blockhash used is from a block strictly before current block.
        // In reference, settle fails if block.number == guesses[settler].block, so success is false.
        // In bug, settle can succeed with block.number >=, so success may be true when block.number == guessed block.
        assertTrue(!success, "settle should not succeed using a blockhash from the current block");
    }
}

