pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(bytes32 guess, uint8 blockOffset) public {
        // Admissible domain: offset 1..255 (stored block is block.number + 1)
        vm.assume(blockOffset > 0);

        address guesser = address(0x1000);
        vm.deal(guesser, 1 ether);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(guess);

        vm.roll(block.number + blockOffset);

        // Record balance before settle
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(guesser);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 balanceAfter = address(c).balance;

        // The reference behavior: after settle, the guesser's stored block is reset to 0
        // regardless of blockhash match. This reset always happens in the reference.
        // In the mutant, the stored block reset also always happens (same code).
        // The difference is in whether the guess matched the computed answer.
        // We capture this difference by checking that the ETH transfer occurred
        // if and only if guess == keccak256(abi.encodePacked(blockhash(storedBlock))).
        // Since we don't have direct access to the stored block after reset, we compare
        // the final balance: in reference, transfer happens only on exact match of stored hash;
        // in mutant, transfer happens on match of current-1 hash.
        // The property: the final balance of C equals balanceBefore - 2 ether iff
        // guess == keccak256(abi.encodePacked(blockhash(block.number - blockOffset + 1)))
        // (the stored block was block.number - blockOffset + 1, the block at which lockInGuess was called + 1).
        // We can assert that the balance change is consistent with the reference logic.
        uint256 storedBlock = block.number - blockOffset + 1;
        bytes32 referenceAnswer = keccak256(abi.encodePacked(blockhash(storedBlock)));
        bool expectedTransfer = (guess == referenceAnswer);
        uint256 expectedBalance = expectedTransfer ? balanceBefore - 2 ether : balanceBefore;

        assertTrue(balanceAfter == expectedBalance);
    }
}

