pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockBlockOffset, uint256 settleBlockOffset, bytes32 guess) public {
        vm.assume(lockBlockOffset > 0);
        vm.assume(settleBlockOffset > 0);
        vm.assume(lockBlockOffset + settleBlockOffset < 256);

        // Fund the contract: 2 ether total for two guesses
        vm.deal(address(this), 3 ether);
        vm.deal(address(0x1), 1 ether);
        vm.deal(address(0x2), 1 ether);

        // Deploy and fund C
        payable(address(c)).transfer(2 ether);

        // First guess from address(0x1) at block.number + lockBlockOffset
        vm.roll(block.number + lockBlockOffset);
        vm.prank(address(0x1));
        c.lockInGuess{value: 1 ether}(guess);

        // Second guess from address(0x2) at the same block
        vm.prank(address(0x2));
        c.lockInGuess{value: 1 ether}(guess);

        // Settle after settleBlockOffset blocks
        vm.roll(block.number + settleBlockOffset);

        bool refOk;
        try c.settle() {
            refOk = true;
        } catch {
            refOk = false;
        }

        // Both settlers share the same guess and the same stored block;
        // the reference uses that block's hash for both; the mutant uses block.number-1,
        // which will differ if settleBlockOffset != 1. Hence one settle can succeed when
        // the other fails only in the mutant, breaking the invariant that the outcome
        // for the same guess/stored-block is the same.
        vm.prank(address(0x2));
        bool refOk2;
        try c.settle() {
            refOk2 = true;
        } catch {
            refOk2 = false;
        }

        assertTrue(refOk == refOk2);
    }
}

