pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guess, uint64 blockAdvance) public {
        // blockAdvance gives the number of blocks to advance after lockInGuess before calling settle
        vm.assume(blockAdvance >= 1 && blockAdvance <= 256);

        // Deploy the reference contract and fund it with the required 1 ether deposit
        vm.deal(address(this), 100 ether);
        c{value: 1 ether}();

        // Lock a guess with a new actor (address(uint160(0x1234)))
        address actor = address(uint160(0x1234));
        vm.deal(actor, 100 ether);
        vm.prank(actor);
        c{value: 1 ether}.lockInGuess(guess);

        // Advance the chain by the specified number of blocks
        vm.roll(block.number + blockAdvance);

        // Record balances before settle
        uint256 balCBefore = address(c).balance;
        uint256 balActorBefore = actor.balance;

        // Call settle as the actor
        vm.prank(actor);
        c.settle();

        // Compute the correct answer according to the reference logic
        // The reference uses the block number stored during lockInGuess, which is (initialBlock + 1)
        // where initialBlock = block.number at the time of lockInGuess before blockAdvance
        uint256 storedBlock = (block.number - blockAdvance) + 1;
        bytes32 correctAnswer = keccak256(abi.encodePacked(blockhash(storedBlock)));

        // The reference invariant: the actor's balance increases by 2 ether if and only if the guess matches the correctAnswer
        bool referencePayout = (guess == correctAnswer);
        uint256 balanceChange = actor.balance - balActorBefore;
        if (referencePayout) {
            assertTrue(balanceChange == 2 ether);
            assertTrue(balCBefore == 2 ether);
        } else {
            assertTrue(balanceChange == 0);
        }
    }
}

